    {
      "name": "Polynomial.sum_monomial_eq",
      "type": " {R : Type u} [Semiring R] (p : Polynomial R) : (p.sum fun n a => (Polynomial.monomial n) a) = p",
      "module": "Mathlib.Algebra.Polynomial.Basic"
    },
    {
      "name": "Polynomial.sum_monomial_index",
      "type": " {R : Type u} [Semiring R] {S : Type u_1} [AddCommMonoid S] {n : ℕ} (a : R) (f : ℕ → R → S) (hf : f n 0 = 0) : ((Polynomial.monomial n) a).sum f = f n a",
      "module": "Mathlib.Algebra.Polynomial.Basic"
    },
    {
      "name": "MvPolynomial.sum_monomial_eq",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {A : Type u_2} [AddCommMonoid A] {u : σ →₀ ℕ} {r : R} {b : (σ →₀ ℕ) → R → A} (w : b u 0 = 0) : ((MvPolynomial.monomial u) r).coeff.sum b = b u r",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.support_sum_monomial_coeff",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (p : MvPolynomial σ R) : ∑ v ∈ p.support, (MvPolynomial.monomial v) (p.coeff v) = p",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.monomial_sum_prod",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {α : Type u_2} (s : Finset α) (f : α → σ →₀ ℕ) (g : α → R) : (MvPolynomial.monomial (∑ i ∈ s, f i)) (∏ i ∈ s, g i) = ∏ i ∈ s, (MvPolynomial.monomial (f i)) (g i)",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.monomial_sum_one",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {α : Type u_2} (s : Finset α) (f : α → σ →₀ ℕ) : (MvPolynomial.monomial (∑ i ∈ s, f i)) 1 = ∏ i ∈ s, (MvPolynomial.monomial (f i)) 1",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.monomial_sum_index",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {α : Type u_2} (s : Finset α) (f : α → σ →₀ ℕ) (a : R) : (MvPolynomial.monomial (∑ i ∈ s, f i)) a = MvPolynomial.C a * ∏ i ∈ s, (MvPolynomial.monomial (f i)) 1",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.monomial_finsupp_sum_index",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {α : Type u_2} {β : Type u_3} [Zero β] (f : α →₀ β) (g : α → β → σ →₀ ℕ) (a : R) : (MvPolynomial.monomial (f.sum g)) a = MvPolynomial.C a * f.prod fun a b => (MvPolynomial.monomial (g a b)) 1",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "Algebra.Generators.ofComp_toAlgHom_monomial_sumElim",
      "type": " {R : Type u} {S : Type v} {ι : Type w} [CommRing R] [CommRing S] [Algebra R S] {ι' : Type u_3} {T : Type u_7} [CommRing T] [Algebra R T] [Algebra S T] [IsScalarTower R S T] (Q : Algebra.Generators S T ι') (P : Algebra.Generators R S ι) (v₁ : ι' →₀ ℕ) (v₂ : ι →₀ ℕ) (a : R) : (Q.ofComp P).toAlgHom ((MvPolynomial.monomial (v₁.sumElim v₂)) a) = (MvPolynomial.monomial v₁) ((MvPolynomial.aeval P.val) ((MvPolynomial.monomial v₂) a))",
      "module": "Mathlib.RingTheory.Extension.Generators"
    },
    {
      "name": "MonomialOrder.coeff_prod_sum_degree",
      "type": " {σ : Type u_1} {m : MonomialOrder σ} {R : Type u_2} [CommSemiring R] {ι : Type u_3} (P : ι → MvPolynomial σ R) (s : Finset ι) : (∏ i ∈ s, P i).coeff (∑ i ∈ s, m.degree (P i)) = ∏ i ∈ s, m.leadingCoeff (P i)",
      "module": "Mathlib.RingTheory.MvPolynomial.MonomialOrder"
    },
    {
      "name": "MonomialOrder.degree_sum_le",
      "type": " {σ : Type u_1} {m : MonomialOrder σ} {R : Type u_2} [CommSemiring R] {α : Type u_3} {s : Finset α} {f : α → MvPolynomial σ R} : m.toSyn (m.degree (∑ x ∈ s, f x)) ≤ s.sup fun x => m.toSyn (m.degree (f x))",
      "module": "Mathlib.RingTheory.MvPolynomial.MonomialOrder"
    },
    {
      "name": "MonomialOrder.withBotDegree_sum_le",
      "type": " {σ : Type u_1} {m : MonomialOrder σ} {R : Type u_2} [CommSemiring R] {α : Type u_3} {s : Finset α} {f : α → MvPolynomial σ R} : m.toWithBotSyn (m.withBotDegree (∑ x ∈ s, f x)) ≤ s.sup fun x => m.toWithBotSyn (m.withBotDegree (f x))",
      "module": "Mathlib.RingTheory.MvPolynomial.MonomialOrder"
    }
  ]
}
